# Perceptron by hand: the AND/OR weights, the NOT-gate learning trace, and XOR's failure
import numpy as np
step = lambda h: 1 if h >= 0 else 0
X2 = [(0, 0), (0, 1), (1, 0), (1, 1)]
for name, (w0, w1, w2), target in [("AND", (-1, 0.75, 0.75), [0, 0, 0, 1]), ("OR", (-1, 2, 2), [0, 1, 1, 1])]:
    out = [step(w0 + w1 * a + w2 * b) for a, b in X2]
    print(f"{name}: w0={w0}, w1={w1}, w2={w2} -> outputs {out} target {target} {'OK' if out == target else 'WRONG'}")

def train(data, w, eta=1.0, epochs=10, verbose=True):
    w = np.array(w, float)
    for ep in range(1, epochs + 1):
        changed = False
        for x, t in data:
            xt = np.r_[1, x]; h = w @ xt; y = step(h)
            if verbose: print(f"  epoch {ep}: x={x}, t={t}, h={h:+.2f}, y={y}", end="")
            if y != t: w = w + eta * (t - y) * xt; changed = True; print(f"  -> update w = {w}" if verbose else "", end="")
            if verbose: print()
        if not changed: return w, ep
    return w, None
print("NOT gate (w0 = w1 = 0, eta = 1):")
w, ep = train([((0,), 1), ((1,), 0)], [0, 0]); print("converged in epoch", ep, "final [w0, w1] =", w)
for name, t in [("AND", [0, 0, 0, 1]), ("OR", [0, 1, 1, 1]), ("XOR", [0, 1, 1, 0])]:
    w, ep = train(list(zip(X2, t)), [0, 0, 0], eta=1.0, epochs=100, verbose=False)
    print(f"{name}: {'converged in epoch ' + str(ep) + ', w = ' + str(np.round(w, 2)) if ep else 'did NOT converge in 100 epochs (not linearly separable)'}")
